FIX = {
"3b0f86f2eaa010cc": 'Получить после завершения "{0}"',
"2a6f1998027e5f86": 'Завершите испытание Башни Испытаний во время события\nи заберите щедрые ограниченные награды!',
"36df2c91120df511": 'Разблокирует второй\nуникальный навык вознесения <color=#EFD27F>Берила и Хасны</color>',
"0de3b7a50b1f0162": 'Но Меч Конвалларии не стремится\nни к славе, ни к известности.\nМы только хотим принести\nмир и свободу Ирии.',
"de5606fd873318a9": 'Похоже, они напали\nна купцов, проходивших мимо.',
"0e40895021d781ed": 'Почему солдаты Ирии\nпоявились здесь?',
"d913f8adc7405d1e": 'Тюрьма Повешенных — вот где\nвам, грязнулям, и место!',
"746a8a412a2e805b": 'Враг… уже…\nздесь?… Кто…',
"41338782464a85a9": 'Это едва ли является сюрпризом. Если кто-то и мог взять на себя эту обязанность после Лейлы, то это, вероятно, она. Однако то, что озадачило меня, — это отсутствие какой-либо реакции у Равии.\nВыражение её лица было не спокойным, а скорее пустым.',
"2b4860449db5fac8": 'Мошенник убегает в панике. «Разве денег недостаточно?! Есть ли что-то более важное, чем деньги в этом мире?»\n«Я даже не умер, так какой толк от денег!» Вы в ярости опрокидываете его палатку.\n«Помощь! Кто-нибудь! Я заплачу! Я заплачу!»\nНесколько крепких гладиаторов выпрыгивают из-за повозки и окружают вас…',
"f55b720f5c7ac54f": 'Банда бунтующих Темносветов захватила старый замок. Королевская Армия выдала\nМечу Конвалларии задание его очистить. Подумав немного, вы решаете совершить рейд.',
"917a3d2a0fd1e856": 'Эта могущественная нация, которая когда-то завоевала Ирию, теперь держится в стороне от текущих конфликтов.',
"ed57d63c49a37ffe": 'Эта фракция в северо-восточных горах наблюдает за бедами Ирии с холодным безразличием.',
"7f767570a1c44c00": 'Союз, Папские Штаты и Империя Эламан сформировали военный союз, который разделил всю территорию Ирии между ними.',
"715030924b2c7a04": 'Боец из Группы Наёмников Меча Конвалларии пришёл к вам и попросил разрешение вернуться в Крепость Перекрёстка и поискать\nостанки своего боевого товарища. Вы согласились с его просьбой и вернули останки Ноэля, его боевого товарища, ему.',
"18989acb93360b0b": 'Крепость Перекрёстка вошла в свой последний сон…\nИ трубы войны прозвучат с наступлением дня.\nСпасибо за то, что освещали путь нашей судьбе до сих пор. Пожалуйста, отдохните, ибо путь откроется в будущем…\n(Спасибо за участие в этом тесте, и последующий контент будет открыт в будущем.)',
"760c8d37a192587f": 'Меч Конвалларии подписал контракт о партнёрстве с Союзом.\nОрден полностью контролировал бы и защищал город.\n|Следующий ход Союза состоял в атаке на Крепость Перекрёстка, чтобы полностью\nконтролировать этот ключевой транспортный узел. Для достижения этой цели Орден\nсобирался построить военный лагерь рядом с городом в качестве центра снабжения.\n|Меч Конвалларии сыграл бы значительную роль в строительстве…',
"decf9885a97d6953": 'После непрерывных боёв\nОрден и Меч Конвалларии успешно изолировали Крепость Перекрёстка.\n|Армии Союза и Папских Штатов Родинии начнут генеральное наступление\nс обеих сторон.\n|Будущее Королевской Армии\nкажется под угрозой…',
"39baebab34401790": 'В отчаянной войне многие беспомощные мирные жители были обмануты\nи бежали в Рудничную Яму на юго-востоке.\n|Темносвет, который насильно захватил Рудничную Яму,\nвоспользовался возможностью для расширения. После этого они перестали\nскрываться и вышли на открытое место.',
"4738424d22024112": 'Несколько недель спустя война бушевала как лесной пожар в Ирии.\nКоролевская Армия, Союз и Папские Штаты продолжали\nнаращивать силы.\n|И так три стороны столкнулись на всех фронтах.\nВ результате множество людей были вынуждены покинуть свои дома и оказались в отчаянном положении.',
"5dd238247ef132c1": 'Хотя осада Крепости Перекрёстка Союзом провалилась,\nКоролевская Армия, страдающая от внутренних и внешних проблем,\nне могла собрать силы для контратаки.\n|На протяжении последних нескольких месяцев две фракции противостояли друг другу,\nиспользуя Крепость как разделительную линию, участвуя в мелких стычках,\nа не в полномасштабных битвах.\n|Неудачное наступление Королевской Армии дало Союзу возможность\nвосстановить свои силы. Более того, разведданные указывают на то, что\nнесмотря на некоторые победы, среди населения растёт желание, чтобы\nКоролевская Армия начала мирные переговоры с Союзом.\n|Эти настроения ещё больше подорвали решимость Королевской Армии\nпродолжать борьбу.',
"ef3754e4334bfc72": 'После тяжёлой битвы с Папскими Штатами и Королевской Армией\nСоюз вновь окружил Крепость Перекрёстка.\nНа этот раз рыцари проявили непоколебимую\nрешимость, поклявшись захватить Крепость Перекрёстка.\n|Однако Королевская Армия смогла значительно укрепить\nоборону Крепости Перекрёстка с помощью Папских Штатов.\n|Меч Конвалларии взял на себя\nмиссию атаки на крепость…\nкоторая решит судьбу Ирии.',
"5e22c5bb5b7a428e": 'Несмотря на все усилия Королевской Армии,\nони не смогли остановить продвижение Ордена к Замку Морнрейс.\n|С победой в пределах досягаемости боевой дух Ордена достиг апогея.\nОднако Королевская Армия была деморализована и испытывала нехватку припасов.\nДве стороны начнут финальную битву вокруг Замка Морнрейс.\nНо победитель битвы уже ясен…',
"36f3592b8982db25": 'Заплатив огромную цену, Орден наконец разрушил Замок Морнрейс.\n|Множество аристократов, поддерживавших Данталиона, офицеры, выступавшие за войну,\nи члены Повешенных были заключены в тюрьму или казнены.\n|Падение Замка Морнрейс ознаменовало официальный конец\nгражданской войны в Ирии.\n|Это также означало, что Август наконец получил время\nдля решения внутренних проблем Авангардного Ордена…',
"e80a45072d80e33d": 'Прошёл месяц с момента инцидента в Вейверане,\nи контрповстанческие действия Королевской Армии всё ещё находились в тупике.\nВ этот период беспокойства Принц Данталион провёл государственные похороны\nубитой Принцессы Инанны в Замке Морнрейс.\n|На похоронах Данталион опроверг слухи об инциденте в Вейверане\nи сказал, что Папские Штаты и Союз организовали его.\nОн призвал народ объединиться и изгнать захватчиков.\n|Похороны и речь подняли боевой дух Королевской Армии,\nи они вновь пошли на войну.',
"8543d2e16be42a37": 'Теперь Союз инициировал новый раунд крупномасштабного наступления,\nчтобы вновь вернуть контроль над Крепостью Перекрёстка.\n|В попытке предотвратить быстрое поражение\nКоролевской Армии Союзом Папские Штаты объявили о своей поддержке Ирии,\nпообещав остановить наступающие силы Союза.',
"e03608d314fe9ce7": 'Изнурительная вторая битва за Крепость Перекрёстка\nнаконец закончилась победой Союза,\nчто означало, что Союз получил решающие преимущества.\n|Ослабленная Королевская Армия отказалась от позиций на Реке Ирия.\nТеперь, собравшись в Замке Морнрейс, они готовятся\nк последней стойке, используя замок.\n|Потеряв большую часть своих земель и почти все свои ресурсы,\nотчаянные беженцы теперь толпами стекаются в Замок Морнрейс,\nчто ещё больше усугубляет ситуацию.\n|Все знают, что война невыносима.\nТеперь Королевская Армия должна решить, сражаться или сдаться…',
"42e163c2fb4eea62": 'Союз, оккупировавший Крепость Перекрёстка,\nне был доволен только победой.\nПосле короткого отдыха Орден атаковал Замок Морнрейс.\nНо Королевская Армия Ирии не сдавалась так легко.\n|Они построили многоуровневую оборону, чтобы остановить продвижение Ордена,\nи отправили партизанские отряды с Повешенными,\nчтобы нарушить тыл Ордена.\nСледующий этап битвы маячит на горизонте…',
"891e14abdb4e890e": 'Вторая гражданская война в Ирии, длившаяся более года,\nзакончилась арестом Принца Данталиона.\nЗамок Морнрейс, столица, открыл свои ворота для сдачи.\n|Как абсолютный победитель этой войны,\nСоюз подписал договор с Лютфи, вторым принцем королевства.\nОднако вас волнует только то, что Лютфи будет делать с Союзом,\nвеликой угрозой для Ирии…',
"0385b981e87f75a7": 'Хотя ходили слухи, что Союз проведёт мирные переговоры\nпосле своей победы, Орден продолжил своё наступление,\nнаправляясь к Замку Морнрейс после пересечения Реки Ирия.\n|Теперь перед Королевством Ирия есть два варианта:\nсдаться Союзу или продолжить борьбу до верного поражения.\n|В это время Лютфи, который был близким союзником Союза,\nвзял на себя задачу лобовой атаки на Замок Морнрейс.\nДавайте посмотрим, что он нам приготовил…',
"c6264e9fccc19813": 'С другой стороны, Папские Штаты Родинии на юге также воспользовались ситуацией\nи оккупировали бывшую столицу, Город Светлого Сияния,\nукрепив Легион Вейверана.\n|Эта небольшая страна, стратегически расположенная в ключевой позиции,\nвновь вовлечена в войну…',
"74971b43ba49ead9": 'Ситуация быстро ухудшилась. Военная держава,\nСоюз Рыцарских Государств, объявила\nо своей поддержке «требований иридцев против тирании».\n|Они отправили Авангардный Орден и контролировали\nокрестности Города Вейверана.',
"1c946d88d240f334": 'В марте 999 года по Сияющему Календарю парад Дня Святилища\nв Городе Вейверана превратился в вооружённый конфликт,\nв котором погибло или было ранено множество мирных жителей.\n|Принцесса Инанна Ирии, которая пыталась поговорить с демонстрантами,\nтакже погибла во время инцидента.\n|Несколько дней спустя демонстранты сформировали «Легион Вейверана».\nОни утверждали, что нынешний национальный лидер, Принц Данталион,\nдолжен нести ответственность за инцидент в Вейверане.\n|Они требовали, чтобы он отказался от власти и предстал перед судом.\nДанталион же утверждал, что это не что иное, как клевета и восстание,\nи сформировал армию для подавления восстания.',
"cfaea891df1f9dad": 'В тот вечер в Крепости Перекрёстка была проведена грандиозная церемония.\nИридцы, влдерцы и люцианцы все участвовали в веселье.\n|Данталион похвалил достижения как Меча Конвалларии,\nтак и его союзников и щедро наградил солдат.\n|В конце своей речи Данталион проклял\nпредательство коррумпированных аристократов.\nОн поклялся, что справедливое наказание будет исполнено.',
"db31fb64840d4c7b": 'С Фернандо в цепях и Транквиллом на свободе\nостатки Ордена Темносвета были уничтожены,\nи религия была покинута её последователями.\n|После их неустанной борьбы за свободу\nРудничная Яма оказалась под властью Папских Штатов,\nно сомнения в их намерениях начали заполнять воздух.',
"ed6e28327e5a1a50": 'Теперь вы и Саманта отправляетесь в Город Светлого Сияния для аудиенции\nс одним из высших должностных лиц Папских Штатов.',
"5a9538b04edf13c1": 'Война в Ирии продолжала обостряться.\nКоролевская Армия сохраняла боевой дух\nнесмотря на передовое вооружение Союза.\nПротяжённый взаимный конфликт разразился вокруг Крепости Перекрёстка.\n|Обе армии отчаянно стремились расширить свою территорию.\nВ конце концов, разрушения можно было увидеть даже рядом с Городом Конвалларии.',
"33bb9dad57c45b0d": 'По мере того как Папские Штаты продолжали активизировать свою деятельность в Ирии,\nосада Крепости Перекрёстка наконец подошла к концу.\n|Под руководством Принца Данталиона Королевская Армия\nсмогла отразить наступление Союза, но ценой тысяч жизней.\nОбе стороны теперь не имели сил для наступления,\nи поэтому боевые действия прекратились, по крайней мере на время…',
"7dcf4535d6418e5c": 'Королевская Армия раскрыла всем доказательства, предоставленные Мигелем —\nПапские Штаты тайно интенсифицировали и использовали ситуацию в Вейверане.\nКак и Союз, они были одними из инициаторов трагедии в Вейверане.\n|Кроме того, Папские Штаты возглавили убийство двух принцев\nи возложили вину на Союз, чтобы убить двух зайцев одним выстрелом.\n|После того как доказательства были обнародованы, вся страна была в смятении.\nТеперь Папским Штатам предстоит столкнуться с Ирией, объединённой гневом как никогда.\n|Мир, который вы жаждали, обречён быть недостижимым…',
"32567d544052c450": 'Силы, благоприятствующие Папским Штатам, представленные старыми аристократами,\nвоспользовались политическим хаосом в Ирии и сформировали союз\nс Папскими Штатами с целью свержения Союза.',
"4a6a32bd84656648": 'Среди хаоса одновременной смерти двух принцев\nДанталиона и Лютфи Папские Штаты взяли инициативу\nв обвинении Союза в том, что он является вдохновителем убийства.\n|Союз отрицал обвинения и намекал на то, что Папские Штаты\nбыли истинными организаторами ситуации.\n|Однако Папские Штаты обнародовали доказательства, которые\nдоказали, что Союз стоял за трагедией в Вейверане.\nИридцы были потрясены, и население\nрезко повернулось в пользу Папских Штатов.',
"51f52b9efbaf0e8a": 'Город Светлого Сияния, когда-то столица Ирии, когда она была марионеточным государством,\nтеперь служит местом амбиций Папских Штатов.\n|Теперь нация, когда-то закованная в цепи и эксплуатируемая, разгромила своих врагов\nдо их последнего оплота, отвоевав большую часть своих территорий.\n|В настоящее время остаётся только Город Светлого Сияния, последняя крепость.',
"f6fc5818f377049b": 'План, который вы создали, был успешно реализован.\nКроме того, повстанцы во главе с Эддой объявили, что\nприсоединятся к Королевской Армии.\nБольше иридцев, угнетённых Папскими Штатами, восстали.\n|Военные и гражданские лица Ирии с беспрецедентно высоким боевым духом\nобъединились под знаменем Королевы Инанны.',
"2c24abe660138b09": 'По мере того как восстание иридского народа нарастало, ослабленные и\nистощённые Папские Штаты оказались неспособны к дальнейшим наступлениям.\nСитуация становилась ещё более неблагоприятной для Папских Штатов.',
"d8dc155ef11587c2": 'Бишоп Карис вызвал Саманту и вас в Город Светлого Сияния.\nТам вас попросили отправиться в дипломатическую миссию в Замок Морнрейс снова\nдля мирных переговоров с Принцессой Инанной.\nНа этот раз Карис пообещал серию крупных уступок.\n|Хотя шансы были всё ещё невелики,\nперед лицом войны, которая уже принесла столько жертв.\nСаманта, жаждущая мира, приняла задачу\nкак спасение.\n|Когда вы выходите из зала,\nмолодая девушка преграждает вам путь.',
"bcac8c6743bf7c4b": 'Смерть Тааира оказала небольшое влияние на ситуацию.\nНо по мере того как восстание иридского народа нарастало, ослабленные и\nистощённые Папские Штаты оказались неспособны к дальнейшим наступлениям.\nСитуация становилась ещё более неблагоприятной для Папских Штатов.',
"3c3ad6b27603cc93": 'Принцесса Инанна произнесла страстную речь,\nпризывая всех иридцев объединиться в защиту своей страны.\nОбъединённые иридцы оказались сильнее, чем ожидали Папские Штаты,\nблокировав их наступление и вынудив их отступить в Город Вейверана.\n|В Городе Вейверана население всё больше противилось\nправлению Папских Штатов, вынуждая их подавлять инакомыслие.',
"3d9b0f787d1aafec": 'С провалом мирных переговоров Папские Штаты и Ирия\nразвязали всеобщую войну.\nПапские Штаты захватили заброшенный Город Вейверана и привели\nцикл в движение ещё раз…',
"ee2b32852886f080": 'В конце концов, коалиционные силы Ирии и Папских Штатов\nодержали решающую победу.\nСоюз был полностью разгромлен, его фронт разбит.\nАвгуст и его рыцари, видя, что кубик брошен, бежали с поля боя.\nВ Городе Светлого Сияния была проведена грандиозная церемония в честь победы.\nОтличное выступление Меча Конвалларии в решающей битве\nзаслужило высокую похвалу от самого Бишопа Кариса.\n|Мощь Союза ослабла, и само его существование поставлено под вопрос.\nИрия же теперь управлялась старыми аристократами,\nсторонниками Папских Штатов. Было ясно, что план Кариса\nвоплощается в жизнь, и победа близка.\n|Всем казалось, что мир уже на расстоянии вытянутой руки.',
"cdf8ae98f9568951": 'С обострением войны в Ирии\nСоюз отогнал Королевскую Армию к Крепости Перекрёстка,\nцентральному оплоту Ирии, который имеет значительное стратегическое преимущество.\n|Увидев возможность, Темносвет, группа фанатичных культистов,\nзахватил Рудничную Яму и отправил свои силы в окрестности,\nв конце концов осадив Город Конвалларии.\n|С помощью Саманты Меч Конвалларии отогнал культистов\nи заключил союз с Папскими Штатами для борьбы с Темносветом.\nЭто будет долгая война с неизвестным будущим.',
"c87debb3fc64495f": 'Вы решили положить конец всему этому собственными руками —\nостановить войну, которая никогда не должна была произойти,\nи найти истинный путь к свету…',
"46f279e172370c0b": 'Фактический правитель Ирии, Принц Данталион, убедил различные\nсилы сформировать коалицию.\nОпираясь на стратегический оплот Крепости Перекрёстка,\nони сорвали первое наступление Авангардного Ордена.',
"694215944c3ffacf": 'В 999 году Сияющего Календаря\nбеспорядки в Городе Вейверана погрузили Королевство Ирия в хаос.\nПод предлогом защиты общественного порядка|и судебного разбирательства над виновниками трагедии\nСоюз организовал Авангардный Орден для входа в Ирию.',
"d1812a3c728c1fe8": 'Судьба Ирии будет решена захватом Крепости Перекрёстка.\nПосле короткого отдыха обе силы вновь заперты\nв жестокой борьбе за перетягивание каната. На протяжённом боевом фронте как нападающие,\nтак и защитники отчаянно ищут решающий прорыв…',
"f3f29b82bafb41f2": 'На стороне Папских Штатов силы, воссоединившиеся во имя восстановления,\nвпали в хаос после потери своего юридического и морального основания.\nЛояльные сторонники старой королевской семьи выбрали следовать за Тааиром,\nно большинство наёмников и интегрированных вооружённых групп бежали.\n|По мере того как Ирия приближалась к победе,\nбитва возобновилась односторонним образом.',
"eb0d9acfd4416bba": 'При посредничестве Саманты\nПринцесса Инанна неожиданно согласилась возобновить мирные переговоры.\nПроведённые в Замке Морнрейс как тайная встреча,\nмирные переговоры дали неожиданный результат.\n|Король Фарис, живший в уединении много лет, официально\nотрёкся бы от престола и передал трон Принцу Тааиру старого Государства Ирия.\nПринцесса Инанна лично председательствовала бы на церемонии, что означало бы\nуспешное восстановление Государства Ирия.\n|Однако это также означало, что Ирия вновь станет марионеточным государством,\nуправляемым Папскими Штатами.\nБишоп Карис счёл внезапную победу невероятной,\nи условия было трудно принять многим иридцам.\n|Несмотря на скептицизм, непоколебимая решимость Принцессы Инанны\nобеспечила подготовку церемонии, ознаменовав отречение\nстарого короля и вознесение нового…',
"f4d318eecf696f90": 'План продвигается вперёд, но предстоящие координация\nи посредничество кажутся более сложными, чем ожидалось…',
"08ea0770b71c9b26": 'После тщательной подготовки грандиозный Фестиваль Конвалларии начался\nпо расписанию. Торговцы стекались на мероприятие, и представители\nразличных фракций прибывали один за другим. Город Конвалларии\nбыл в состоянии необычного возбуждения.\n|К вашему удивлению, Союз и Королевская Армия,\nкоторые молчали и не отвечали, также отправили Сафию\nи Глорию в качестве своих представителей для участия.',
"445f1757dd56f657": 'Несмотря на небольшие шансы на победу, чтобы защитить город,\nвы решаете вступить в смертельный бой с врагом.',
"fc040a99b52b6e57": 'Для города, уже истощённого ресурсами,\nэто, несомненно, добавляет оскорбление к ущербу…\n|Несмотря на предупреждение Саманты, у вас больше нет\nдостаточно времени для подготовки к битве.',
"b0d4a5e2902fd921": 'Сквозь палящие пески и бури,\nчто вас ждёт в конце пути?\nБудет ли это клинок, который разрубит тупик,\nили мираж оживлённого рынка?',
"0e4e0c7793e3dff5": 'Темносвет нависает, отбрасывая тень столь огромную, что торговля\nна Торговом Посту находится в застое уже долгое время.\nВ поисках прорыва вы решаете направиться\nна восточную границу Ирии — в Оазис Рабиа.',
"f966c9f508d12cc8": 'Чтобы обратить вспять текущий затруднительный процесс,\nТорговому Посту срочно необходимо расти и развиваться…',
"1929ad6b8345a5bd": 'Торговые пути заблокированы, продажи падают,\nпоток капитала затруднён — торговцы копят товары,\nвызывая рост цен…',
"df1090f42d13c8a6": 'Торговый Пост города находится на подъёме,\nно Темносвет, как облака, затмевающие рассвет,\nбыстро расширяется и распространяется по всему Королевству Ирия.',
"6f35543a4f68c521": 'Темносвет на горизонте, готовясь к\nвсеобщему наступлению на Город Конвалларии.',
"fdf915d5a03828b5": 'Чтобы положить конец войне раз и навсегда,\nоставался только один решающий шаг — полностью\nподорвать преимущества торговли оружием.',
"1c4f4e5459eefd55": 'Мотивированные желанием мира, все фракции\nотказались поставлять оружие на войну. Союз и\nКоролевская Армия были вынуждены объявить временное перемирие.\n|Битва за Крепость Перекрёстка достигла тупика, и\nвнезапная остановка конфликта взволновала тех, кто был\nзаинтересован в получении прибыли от войны. Они беспокойны\nи готовы вновь разжечь пламя войны при первой же возможности.',
"d2e5b96872100b3f": 'Поражение Темносвета временно сняло давнюю\nтень над городом.\n|Благодаря вашим усилиям жизнь горожан постепенно\nвернулась в норму. Торговые пути открылись, цены стабилизировались, и\nторговля с различными фракциями восстановилась.',
"31b6c200489e0bd1": 'Однако, хотя война официально закончилась,\nбитва за прибыль и справедливость только что началась…',
"315b8909b983ad27": 'Под давлением Союз и Королевская Армия согласились\nна перемирие и участие в расследовании.\n|Инанна, прислушиваясь к зову народа, взяла ситуацию под контроль.\n|Она объявила, что Крепость Перекрёстка временно является нейтральной территорией\nи поклялась тщательно расследовать инцидент в Вейверане,\nпообещав восстановить истину и мир для народа Ирии.',
"341bc12488a21444": 'События суда вызвали переполох среди населения.\nС разоблачением намерений Папских Штатов люди в целом верили,\nчто все три державы были причастны. Слухи об инциденте в Вейверане\nбыли повсеместны.',
"b79070ec41aa61d7": 'Из-за нехватки как продовольствия, так и медикаментов|голод и раны по-прежнему мучают их.\n|Ваша доброта, стойкость и мудрость станут их единственной надеждой пережить\nэти тяжёлые времена.',
"b3b0f8de2fc64456": 'Союз и Королевская Армия Ирии воевали уже несколько дней.\nБеженцы в спешке бегут из Города Вейверана\nи направляются в Город Конвалларии.',
"81a148c7a0e831da": 'Союз неожиданно объявил атаку на Крепость Перекрёстка.\nОднако стычки начались ещё до того, как столкнулись основные силы.\n|Принц Лютфи, как обычно, закупил продовольствие на Торговом Посту Конвалларии.\nПока он распределял продовольствие среди народа и завоёвывал благоприятную репутацию,\nнеожиданно произошла серия массовых отравлений пищей.\n|Это стало общественным скандалом, который Королевская Армия использовала против Союза.',
"25fd62cc2ae62d8b": 'Лютфи не имел выбора, кроме как переложить ответственность на вас.\nТаким образом, Торговый Пост Конвалларии быстро оказался в водовороте\nпротиворечий. Чтобы стабилизировать трудно завоёванное экономическое развитие,\nвы должны быстро очистить имя Торгового Поста.',
"f55c840efa8a2024": 'Разразилась битва за Крепость Перекрёстка…\nрезультатом стал тупик, при котором ни одна сторона не получила решающего преимущества.\n|В конце концов, обе заплатили огромную цену, но линии фронта\nостались неизменными.\n|Эта война была обречена продолжаться…',
"88c12f98af4e84be": 'Рудничная Яма и Племена Влдер объявили всей Ирии,\nчто они работали вместе, чтобы сформировать новый синдикат добычи люксита\nпод названием «Лиса и Белка».',
"83fb74a94e9d9061": 'К счастью, благодаря вашим долгосрочным усилиям по активному объединению\nи созданию союзов с другими фракциями всё больше людей\nбыли склонны разрешать споры через взаимные интересы.\nПризывы к перемирию начали появляться во Влдере и Рудничной Яме.',
"3b1e3dc2296afe52": 'Последствия первой битвы за Крепость Перекрёстка ещё не утихли.\nСоюз и Королевская Армия неожиданно объявили о предстоящем втором поединке за\nКрепость Перекрёстка.\n|Когда новость распространилась, воздух наполнился криками скорби народа.\nСлишком долго земля была охвачена пеплом и пламенем войны…',
}

def tags(s):
    return sorted(re.findall(r'<[^>]+>', s))

def ph(s):
    return sorted(re.findall(r'\{\w*\}', s))

rows = []
with io.open(SRC, encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if line:
            rows.append(json.loads(line))

assert len(rows) == 80, len(rows)
keys = [r["key"] for r in rows]
missing = [k for k in keys if k not in FIX]
extra = [k for k in FIX if k not in keys]
assert not missing, missing
assert not extra, extra

with io.open(DST, "w", encoding="utf-8", newline="\n") as f:
    for r in rows:
        f.write(json.dumps({"key": r["key"], "ru": FIX[r["key"]]}, ensure_ascii=False) + "\n")

# validate
errors = []
done = {}
with io.open(DST, encoding="utf-8") as f:
    out_rows = [json.loads(l) for l in f if l.strip()]
assert len(out_rows) == 80
assert [o["key"] for o in out_rows] == keys, "order mismatch"
done = {o["key"]: o["ru"] for o in out_rows}

for r in rows:
    en, ru = r["en"], done[r["key"]]
    if en.count("\n") != ru.count("\n"):
        errors.append((r["key"], "newline count", en.count("\n"), ru.count("\n")))
    if tags(en) != tags(ru):
        errors.append((r["key"], "tags", tags(en), tags(ru)))
    if ph(en) != ph(ru):
        errors.append((r["key"], "placeholders", ph(en), ph(ru)))

if errors:
    print("ERRORS:")
    for e in errors:
        print(e)
    sys.exit(1)
print("OK: 80/80 rows, newline counts, <tags> and {placeholders} all match.")
